import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits() {

  const [limits, setLimits] = useState({
    "Food & Groceries": "",
    "Bills": "",
    "Shopping": "",
    "Transport": ""
  });

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSave = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/userdata/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          budgetLimits: limits
        })
      });

      const data = await res.json();

      if (data.success) {
        alert("Data saved successfully!");
      } else {
        alert("Error saving data");
      }
    } catch (err) {
      alert("Server error");
    }
  };

  return (
    <div className="budget-container">
      <h2 className="budget-title">Set Monthly Budget Limits</h2>

      <div className="budget-grid">

        <div className="budget-card">
          <h3>Food & Groceries</h3>
          <input
            type="number"
            className="budget-input"
            value={limits["Food & Groceries"]}
            onChange={(e) =>
              handleChange("Food & Groceries", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Bills</h3>
          <input
            type="number"
            className="budget-input"
            value={limits["Bills"]}
            onChange={(e) =>
              handleChange("Bills", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Shopping</h3>
          <input
            type="number"
            className="budget-input"
            value={limits["Shopping"]}
            onChange={(e) =>
              handleChange("Shopping", e.target.value)
            }
          />
        </div>

        <div className="budget-card">
          <h3>Transport</h3>
          <input
            type="number"
            className="budget-input"
            value={limits["Transport"]}
            onChange={(e) =>
              handleChange("Transport", e.target.value)
            }
          />
        </div>

      </div>

      <button
        className="budget-button"
        onClick={handleSave}   // ✅ DIRECT SAVE
      >
        Save Limits
      </button>
    </div>
  );
}

export default BudgetLimits;
